const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[],token='',editing=null,tab='requests',filter='',statusFilter='all';
const labels={new:'Nouvelle',active:'En cours',done:'Terminée',low:'Basse',normal:'Normale',high:'Haute'};
async function api(path,body,retry=true){const r=await fetch('api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Atlas-Token':token},body:JSON.stringify(body)}:{});if(r.status===403&&body&&retry){token=(await api('session')).token;return api(path,body,false)}const d=await r.json();if(!r.ok)throw Error(d.error||'Erreur API');return d}
function stats(){return `<div class="stats">${[['Demandes au total',rows.length],['À traiter',rows.filter(r=>r.status==='new').length],['En cours',rows.filter(r=>r.status==='active').length],['Terminées',rows.filter(r=>r.status==='done').length]].map(([l,n])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-number">${n}</div><div class="stat-foot">Données de démonstration</div></div>`).join('')}</div>`}
function table(){const view=rows.filter(r=>(statusFilter==='all'||r.status===statusFilter)&&(r.client+' '+r.title).toLowerCase().includes(filter.toLowerCase()));return `<div class="panel table-wrap"><table><thead><tr><th>Demande</th><th>Client</th><th>Priorité</th><th>Statut</th><th>Action</th></tr></thead><tbody>${view.map(r=>`<tr><td class="request-title"><strong>${esc(r.title)}</strong><small>${new Date(r.created).toLocaleDateString('fr-FR')}</small></td><td>${esc(r.client)}</td><td>${esc(labels[r.priority])}</td><td><span class="pill ${r.status==='new'?'warn':''}">${labels[r.status]}</span></td><td><button class="button" data-edit="${r.id}">Modifier</button></td></tr>`).join('')||'<tr><td colspan="5">Aucune demande pour ce filtre.</td></tr>'}</tbody></table></div>`}
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='requests'){$('#content').innerHTML=`${stats()}<div class="filter-row"><input id="search" aria-label="Rechercher une demande" placeholder="Rechercher un client, une demande…" value="${esc(filter)}"><select id="status-filter" aria-label="Filtrer par statut"><option value="all">Tous les statuts</option>${['new','active','done'].map(s=>`<option value="${s}" ${s===statusFilter?'selected':''}>${labels[s]}</option>`).join('')}</select></div><div id="table">${table()}</div>`;$('#search').addEventListener('input',e=>{filter=e.target.value;$('#table').innerHTML=table()});$('#status-filter').addEventListener('change',e=>{statusFilter=e.target.value;$('#table').innerHTML=table()})}else if(tab==='insights')$('#content').innerHTML=stats()+`<section class="panel"><div class="panel-head"><h2>Priorités de l’équipe</h2></div><div class="panel-body"><p>${rows.filter(r=>r.priority==='high'&&r.status!=='done').length} demande(s) prioritaire(s) non terminée(s).</p><p>${rows.length?Math.round(rows.filter(r=>r.status==='done').length/rows.length*100):0} % des demandes fictives sont terminées.</p><div class="callout"><p>Ces mesures décrivent le jeu de démonstration. Elles ne représentent ni de vrais clients ni une validation commerciale.</p></div></div></section>`;else $('#content').innerHTML='<section class="panel"><div class="panel-head"><h2>Un prototype complet, à petite échelle</h2></div><div class="panel-body"><p>QueuePilot permet de créer, rechercher, filtrer et modifier des demandes. Les données sont validées par une API Python puis enregistrées dans SQLite.</p><p>Les changements restent sur ce PC et sont conservés après redémarrage. Aucun compte externe, e-mail, paiement ou suivi public.</p></div></section>'}
function openForm(item){editing=item?.id||null;$('#form-title').textContent=item?'Modifier la demande':'Nouvelle demande';$('#client').value=item?.client||'';$('#request-title').value=item?.title||'';$('#priority').value=item?.priority||'normal';$('#status').value=item?.status||'new';$('#form-error').textContent='';$('#request-dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;render()}if(b.id==='add')openForm();if(b.id==='cancel')$('#request-dialog').close();if(b.dataset.edit)openForm(rows.find(r=>r.id===b.dataset.edit))});
$('#request-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('requests'+(editing?'/'+editing:''),{client:$('#client').value,title:$('#request-title').value,priority:$('#priority').value,status:$('#status').value});rows=(await api('requests')).requests;$('#request-dialog').close();render();$('#toast').textContent='Demande enregistrée sur ce PC.';$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3000)}catch(err){$('#form-error').textContent=err.message}finally{button.disabled=false}});
(async()=>{try{token=(await api('session')).token;rows=(await api('requests')).requests;render()}catch(err){$('#content').textContent='Connexion au prototype impossible : '+err.message}})();
